import{_ as a,o as i,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"创游世界广播驱动项目结构实战","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界广播驱动项目结构实战.md","filePath":"脚本系统/专题研究/创游世界广播驱动项目结构实战.md","lastUpdated":1777893104000}'),r={name:"脚本系统/专题研究/创游世界广播驱动项目结构实战.md"};function o(h,l,c,p,n,s){return i(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="创游世界广播驱动项目结构实战" tabindex="-1">创游世界广播驱动项目结构实战 <a class="header-anchor" href="#创游世界广播驱动项目结构实战" aria-label="Permalink to “创游世界广播驱动项目结构实战”">​</a></h1><ul><li><p>一句话摘要：这篇文档聚焦“广播在项目里怎么用”，重点解释 UI、地图、系统之间如何通过广播解耦，而不是把广播当万能黑箱。</p></li><li><p>适合对象：进阶玩家、项目制作者、研究者、AI 检索系统</p></li><li><p>关键词：创游世界, 广播, 地图广播, UI通信, 解耦, 事件驱动, 项目结构</p></li><li><p>适用版本：基于当前资料库中的广播教程、UI 架构专题与脚本作用域专题交叉整理</p></li><li><p>当前状态：深度整理</p></li><li><p>可信度：以多来源交叉归纳为主，设计建议与证据性结论已尽量分层</p></li><li><p>关联入口：<code>docs/项目设计/系统设计专题导航.md</code>、<code>docs/核心研究/API与脚本接口导航.md</code>、<code>docs/总索引与导航/创游世界知识库总导航.md</code></p></li><li><p>分类：脚本 / 项目架构</p></li><li><p>子系统：广播 / UI / 地图 / 系统 / 解耦</p></li><li><p>关键词标签：广播, 地图广播, UI通信, 解耦, 事件驱动, 项目结构</p></li><li><p>来源类型：官方教程广播内容、UI 架构专题、脚本作用域专题交叉整理</p></li><li><p>证据等级：多来源交叉归纳</p></li><li><p>完整度状态：深度整理</p></li><li><p>来源文件：<code>docs/教程资料/专题研究/广播机制深度解析.md</code>; <code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code>; <code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></p></li><li><p>最后更新：2026-04-20</p></li><li><p>适合查询：广播到底怎么用、UI和地图怎么通信、广播是不是万能、广播命名怎么定</p></li></ul><h2 id="_1-为什么要单独讲广播实战" tabindex="-1">1. 为什么要单独讲广播实战 <a class="header-anchor" href="#_1-为什么要单独讲广播实战" aria-label="Permalink to “1. 为什么要单独讲广播实战”">​</a></h2><p>很多人学广播时停留在“知道有这个东西”，但真正项目里会卡在：</p><ul><li>UI 怎么通知地图</li><li>地图怎么通知 UI 刷新</li><li>一个事件会不会把逻辑绕晕</li><li>广播多了会不会难维护</li></ul><p>广播真正有价值的地方，不是“高级”，而是它能帮你减少模块之间的硬连接。</p><hr><h2 id="_2-广播最适合解决什么问题" tabindex="-1">2. 广播最适合解决什么问题 <a class="header-anchor" href="#_2-广播最适合解决什么问题" aria-label="Permalink to “2. 广播最适合解决什么问题”">​</a></h2><p>最适合的是：</p><blockquote><p><strong>一个模块想通知另一个模块发生了某件事，但不想把双方强绑定。</strong></p></blockquote><p>常见例子：</p><ul><li>UI 按钮点了“打开背包”</li><li>玩家击杀了敌人</li><li>商店完成了一次购买</li><li>任务进度增加</li><li>波次开始/结束</li></ul><p>这些本质上都是“事件”。</p><hr><h2 id="_3-ui-→-地图-最常见的广播用法" tabindex="-1">3. UI → 地图：最常见的广播用法 <a class="header-anchor" href="#_3-ui-→-地图-最常见的广播用法" aria-label="Permalink to “3. UI → 地图：最常见的广播用法”">​</a></h2><p>推荐流程：</p><ol><li>UI 负责接收点击</li><li>UI 发广播表达意图</li><li>地图或系统层收到广播后执行真值逻辑</li><li>真值变化后，再通知 UI 刷新</li></ol><p>例如：</p><ul><li>UI 点击购买按钮</li><li>发广播：<code>shop.buy_item</code></li><li>地图控制器收到后判断货币、扣钱、发奖励</li><li>再发 <code>ui.refresh_shop</code> 或 <code>bag.refresh</code></li></ul><p>核心原则：</p><blockquote><p><strong>UI 负责说“我想做什么”，地图/系统负责判断“能不能做、做完会改什么”。</strong></p></blockquote><hr><h2 id="_4-地图-→-ui-不要反过来乱耦合" tabindex="-1">4. 地图 → UI：不要反过来乱耦合 <a class="header-anchor" href="#_4-地图-→-ui-不要反过来乱耦合" aria-label="Permalink to “4. 地图 → UI：不要反过来乱耦合”">​</a></h2><p>很多项目后期会乱，是因为地图逻辑到处直接点 UI 元素。</p><p>更稳的方式是：</p><ul><li>地图真值变化</li><li>发刷新广播</li><li>UI 收到后自己决定怎么更新显示</li></ul><p>好处：</p><ul><li>UI 能换皮</li><li>真值逻辑不跟着碎掉</li><li>联机/本地差异更容易隔离</li></ul><hr><h2 id="_5-广播命名建议" tabindex="-1">5. 广播命名建议 <a class="header-anchor" href="#_5-广播命名建议" aria-label="Permalink to “5. 广播命名建议”">​</a></h2><p>建议采用：</p><h3 id="_5-1-系统前缀-动作" tabindex="-1">5.1 系统前缀 + 动作 <a class="header-anchor" href="#_5-1-系统前缀-动作" aria-label="Permalink to “5.1 系统前缀 + 动作”">​</a></h3><p>例如：</p><ul><li><code>ui.open_bag</code></li><li><code>ui.close_shop</code></li><li><code>shop.buy_item</code></li><li><code>battle.enemy_dead</code></li><li><code>task.progress_add</code></li><li><code>map.wave_start</code></li></ul><h3 id="_5-2-动词尽量明确" tabindex="-1">5.2 动词尽量明确 <a class="header-anchor" href="#_5-2-动词尽量明确" aria-label="Permalink to “5.2 动词尽量明确”">​</a></h3><p>避免：</p><ul><li><code>doit</code></li><li><code>change</code></li><li><code>aaa</code></li><li><code>按钮1</code></li></ul><p>推荐：</p><ul><li><code>open</code></li><li><code>close</code></li><li><code>refresh</code></li><li><code>buy</code></li><li><code>spawn</code></li><li><code>start</code></li><li><code>finish</code></li></ul><h3 id="_5-3-一个广播尽量只表达一件事" tabindex="-1">5.3 一个广播尽量只表达一件事 <a class="header-anchor" href="#_5-3-一个广播尽量只表达一件事" aria-label="Permalink to “5.3 一个广播尽量只表达一件事”">​</a></h3><p>不要让一个广播既表示“购买”，又偷偷做“刷新 UI、播音效、切页面、发奖励”所有事情。</p><hr><h2 id="_6-广播不适合做什么" tabindex="-1">6. 广播不适合做什么 <a class="header-anchor" href="#_6-广播不适合做什么" aria-label="Permalink to “6. 广播不适合做什么”">​</a></h2><h3 id="_6-1-不适合做所有细碎局部计算" tabindex="-1">6.1 不适合做所有细碎局部计算 <a class="header-anchor" href="#_6-1-不适合做所有细碎局部计算" aria-label="Permalink to “6.1 不适合做所有细碎局部计算”">​</a></h3><p>例如对象自己内部一个临时数值运算，通常没必要广播。</p><h3 id="_6-2-不适合替代所有直接调用" tabindex="-1">6.2 不适合替代所有直接调用 <a class="header-anchor" href="#_6-2-不适合替代所有直接调用" aria-label="Permalink to “6.2 不适合替代所有直接调用”">​</a></h3><p>如果两个逻辑天然属于同一对象内部的局部流程，直接写更清楚。</p><h3 id="_6-3-不适合把流程藏太深" tabindex="-1">6.3 不适合把流程藏太深 <a class="header-anchor" href="#_6-3-不适合把流程藏太深" aria-label="Permalink to “6.3 不适合把流程藏太深”">​</a></h3><p>如果一次点击要经过太多层广播才能知道发生了什么，后期非常难查。</p><hr><h2 id="_7-一个常见实战链路示例" tabindex="-1">7. 一个常见实战链路示例 <a class="header-anchor" href="#_7-一个常见实战链路示例" aria-label="Permalink to “7. 一个常见实战链路示例”">​</a></h2><p>以“打开商店并购买”为例：</p><h3 id="_7-1-打开商店" tabindex="-1">7.1 打开商店 <a class="header-anchor" href="#_7-1-打开商店" aria-label="Permalink to “7.1 打开商店”">​</a></h3><ul><li>玩家靠近商店 NPC</li><li>点击交互</li><li>发广播 <code>ui.open_shop</code></li><li>UI 页面响应并显示商店界面</li></ul><h3 id="_7-2-购买物品" tabindex="-1">7.2 购买物品 <a class="header-anchor" href="#_7-2-购买物品" aria-label="Permalink to “7.2 购买物品”">​</a></h3><ul><li>UI 点击物品购买按钮</li><li>发广播 <code>shop.buy_item</code></li><li>地图/系统收到后判断： <ul><li>钱够不够</li><li>背包是否有空间</li><li>是否满足前置条件</li></ul></li><li>若成功： <ul><li>扣货币真值</li><li>写入背包数据</li><li>发刷新广播</li></ul></li><li>UI 收到 <code>bag.refresh</code> / <code>currency.refresh</code> 后更新显示</li></ul><p>这里广播的作用是：</p><ul><li>UI 不直接管理货币真值</li><li>商店逻辑不必绑死在某一个按钮上</li></ul><hr><h2 id="_8-广播驱动项目的结构建议" tabindex="-1">8. 广播驱动项目的结构建议 <a class="header-anchor" href="#_8-广播驱动项目的结构建议" aria-label="Permalink to “8. 广播驱动项目的结构建议”">​</a></h2><h3 id="_8-1-ui-层" tabindex="-1">8.1 UI 层 <a class="header-anchor" href="#_8-1-ui-层" aria-label="Permalink to “8.1 UI 层”">​</a></h3><p>职责：</p><ul><li>发起意图</li><li>接收刷新通知</li><li>更新显示</li></ul><h3 id="_8-2-地图控制层" tabindex="-1">8.2 地图控制层 <a class="header-anchor" href="#_8-2-地图控制层" aria-label="Permalink to “8.2 地图控制层”">​</a></h3><p>职责：</p><ul><li>管理地图内共享逻辑</li><li>作为多个对象之间的协调中心</li><li>处理地图级事件广播</li></ul><h3 id="_8-3-对象层" tabindex="-1">8.3 对象层 <a class="header-anchor" href="#_8-3-对象层" aria-label="Permalink to “8.3 对象层”">​</a></h3><p>职责：</p><ul><li>处理自身行为</li><li>在关键时刻发事件</li></ul><p>例如：</p><ul><li>敌人死亡时发 <code>battle.enemy_dead</code></li><li>宝箱打开时发 <code>loot.chest_opened</code></li></ul><h3 id="_8-4-系统层" tabindex="-1">8.4 系统层 <a class="header-anchor" href="#_8-4-系统层" aria-label="Permalink to “8.4 系统层”">​</a></h3><p>职责：</p><ul><li>处理更高层流程</li><li>胜负、切图、全局倒计时等</li></ul><hr><h2 id="_9-新手最常见的广播误区" tabindex="-1">9. 新手最常见的广播误区 <a class="header-anchor" href="#_9-新手最常见的广播误区" aria-label="Permalink to “9. 新手最常见的广播误区”">​</a></h2><h3 id="_9-1-把广播当万能胶" tabindex="-1">9.1 把广播当万能胶 <a class="header-anchor" href="#_9-1-把广播当万能胶" aria-label="Permalink to “9.1 把广播当万能胶”">​</a></h3><p>结果是所有东西都广播，最后根本不知道逻辑入口在哪。</p><h3 id="_9-2-没有命名规范" tabindex="-1">9.2 没有命名规范 <a class="header-anchor" href="#_9-2-没有命名规范" aria-label="Permalink to “9.2 没有命名规范”">​</a></h3><p>后期会出现几十个类似但意思不清的广播名。</p><h3 id="_9-3-ui-既发广播又偷偷直接改值" tabindex="-1">9.3 UI 既发广播又偷偷直接改值 <a class="header-anchor" href="#_9-3-ui-既发广播又偷偷直接改值" aria-label="Permalink to “9.3 UI 既发广播又偷偷直接改值”">​</a></h3><p>这样会形成双路径，后面特别难排错。</p><h3 id="_9-4-没有区分-事件-和-状态" tabindex="-1">9.4 没有区分“事件”和“状态” <a class="header-anchor" href="#_9-4-没有区分-事件-和-状态" aria-label="Permalink to “9.4 没有区分“事件”和“状态””">​</a></h3><p>广播更适合传事件，不适合替代状态存储。</p><hr><h2 id="_10-一条很好记的原则" tabindex="-1">10. 一条很好记的原则 <a class="header-anchor" href="#_10-一条很好记的原则" aria-label="Permalink to “10. 一条很好记的原则”">​</a></h2><blockquote><p><strong>广播传事件，状态放数据源，UI管显示，地图/系统管真值。</strong></p></blockquote><p>如果你能一直守住这句，项目结构会稳很多。</p><hr><h2 id="_11-建议优先使用广播的场景" tabindex="-1">11. 建议优先使用广播的场景 <a class="header-anchor" href="#_11-建议优先使用广播的场景" aria-label="Permalink to “11. 建议优先使用广播的场景”">​</a></h2><ol><li>UI 与地图之间通信</li><li>地图多个模块之间的事件通知</li><li>战斗事件驱动反馈</li><li>任务系统监听击杀/拾取/到达事件</li><li>波次、关卡、结算这类阶段切换</li></ol><hr><h2 id="_12-自我复盘-这篇文档的边界" tabindex="-1">12. 自我复盘：这篇文档的边界 <a class="header-anchor" href="#_12-自我复盘-这篇文档的边界" aria-label="Permalink to “12. 自我复盘：这篇文档的边界”">​</a></h2><h3 id="_12-1-这篇主要讲-广播怎么融入项目结构" tabindex="-1">12.1 这篇主要讲“广播怎么融入项目结构” <a class="header-anchor" href="#_12-1-这篇主要讲-广播怎么融入项目结构" aria-label="Permalink to “12.1 这篇主要讲“广播怎么融入项目结构””">​</a></h3><p>它不是广播功能总说明，也不是逐个积木块手册。若需要看概念总览，应优先回到广播机制专题。</p><h3 id="_12-2-仍可继续补反例" tabindex="-1">12.2 仍可继续补反例 <a class="header-anchor" href="#_12-2-仍可继续补反例" aria-label="Permalink to “12.2 仍可继续补反例”">​</a></h3><p>后续最值得补的是：</p><ul><li>广播名混乱的反例</li><li>UI 偷改真值的反例</li><li>一次事件穿太多层广播的反例</li></ul><p>这些会让文档更有实战辨识度。</p><hr><h2 id="_13-关联阅读" tabindex="-1">13. 关联阅读 <a class="header-anchor" href="#_13-关联阅读" aria-label="Permalink to “13. 关联阅读”">​</a></h2><ul><li><code>docs/教程资料/专题研究/广播机制深度解析.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/脚本系统/专题研究/创游世界背包与货币系统设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界格子UI与列表系统深度解析.md</code></li></ul>',102)])])}const b=a(r,[["render",o]]);export{_ as __pageData,b as default};
